-- Bind real P0 service events to corporate evidence/jobs without mutating product lifecycle.
create table if not exists public.autonomous_service_event_bindings(id uuid primary key default gen_random_uuid(),service_id uuid not null,event_type text not null,department_id integer not null,agent_id uuid references public.autonomous_agents(id),job_id uuid references public.autonomous_jobs(id),source_reference text not null,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),unique(service_id,event_type,source_reference));
alter table public.autonomous_service_event_bindings enable row level security;do $$begin create policy service_bindings_superadmin_read on public.autonomous_service_event_bindings for select to authenticated using(private.is_superadmin());exception when duplicate_object then null;end$$;grant select on public.autonomous_service_event_bindings to authenticated;
create or replace function public.superadmin_bind_service_event(p_service_id uuid,p_event_type text,p_department_id integer,p_source_reference text)
returns public.autonomous_service_event_bindings language plpgsql security definer set search_path=public,private,auth as $$declare r public.autonomous_service_event_bindings%rowtype;begin if auth.uid() is null or not private.is_superadmin()then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;if not exists(select 1 from public.servicios where id=p_service_id)then raise exception 'SERVICE_NOT_FOUND';end if;insert into public.autonomous_service_event_bindings(service_id,event_type,department_id,source_reference)values(p_service_id,btrim(p_event_type),p_department_id,btrim(p_source_reference))on conflict(service_id,event_type,source_reference)do update set source_reference=excluded.source_reference returning * into r;return r;end$$;
revoke all on function public.superadmin_bind_service_event(uuid,text,integer,text) from public;grant execute on function public.superadmin_bind_service_event(uuid,text,integer,text) to authenticated;